import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load texture via cached loader
  const textureUrl = config.imageUrl || '/prism-mock/home/nodes/floating-accent.png';
  const texture = ctx.textureLoader.load(textureUrl);

  // Create plane geometry with atlas region aspect ratio (512:320 = 1.6:1)
  const aspectRatio = 512 / 320;
  const geometry = new THREE.PlaneGeometry(aspectRatio, 1);

  // Create basic material with texture
  const material = new THREE.MeshBasicMaterial({
    map: texture,
    transparent: true,
    toneMapped: false,
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply transform from config or use spec defaults
  if (config.scenePosition) {
    const { x, y, z } = config.scenePosition;
    mesh.position.set(x, y, z);
    if (config.scenePosition.rotationXYZ) {
      const [rx, ry, rz] = config.scenePosition.rotationXYZ;
      mesh.rotation.set(rx, ry, rz);
    }
    if (config.scenePosition.scaleXYZ) {
      const [sx, sy, sz] = config.scenePosition.scaleXYZ;
      mesh.scale.set(sx, sy, sz);
    }
  } else {
    mesh.position.set(-3.2, -0.3, 0);
  }

  group.add(mesh);

  // Setup cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
  };

  // Setup event handlers
  group.userData.handlers = {};

  return group;
}
